#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(optparse); library(jsonlite); library(grid)})

`%||%` <- function(a, b) if (is.null(a)) b else a
op <- parse_args(OptionParser(option_list=list(
  make_option('--signal', type='character'), make_option('--input', type='character'), make_option('--expression', type='character'),
  make_option('--features', type='character'), make_option('--annotations', type='character'),
  make_option('--params', type='character'), make_option('--output', type='character'))))
out <- op$output %||% getwd(); dir.create(out, recursive=TRUE, showWarnings=FALSE)
stale <- c('result.svg','result.pdf','result.png','result.html','figure.json','run.log','signal_data_used.csv','expression_data_used.csv','track_order.csv','error.json')
unlink(file.path(out, stale), force=TRUE)
logmsg <- function(x) cat(sprintf('[%s] %s\n', format(Sys.time(), '%F %T'), x), file=file.path(out,'run.log'), append=TRUE)
fail <- function(m, d='', s='Check input paths, columns, and params.json.') {
  write(toJSON(list(error=m, detail=d, suggestion=s), auto_unbox=TRUE, pretty=TRUE), file.path(out,'error.json'))
  logmsg(paste(m, d)); quit(status=1)
}
tryCatch({
  readtab <- function(f) if (tolower(tools::file_ext(f)) %in% c('tsv','txt')) read.delim(f, check.names=FALSE, stringsAsFactors=FALSE) else read.csv(f, check.names=FALSE, stringsAsFactors=FALSE)
  pfile <- op$params; p <- if (!is.null(pfile) && file.exists(pfile)) fromJSON(pfile, simplifyVector=FALSE) else list()
  relpath <- function(x) { if (is.null(x) || !nzchar(as.character(x)[1])) return(NULL); x <- as.character(x)[1]; if (file.exists(x)) x else if (!is.null(pfile) && file.exists(file.path(dirname(pfile),x))) file.path(dirname(pfile),x) else x }
  val <- function(n, d=NULL, aliases=character()) { x <- p[[n]]; if (is.null(x)) for (k in aliases) if (!is.null(p[[k]])) { x <- p[[k]]; break }; if (is.null(x)) d else x }
  vec <- function(x) if (is.null(x)) character() else trimws(as.character(unlist(x)))
  num <- function(n,d,aliases=character()) { x <- suppressWarnings(as.numeric(unlist(val(n,d,aliases))[1])); if (is.na(x)) d else x }
  boo <- function(n,d=FALSE,aliases=character()) { x<-val(n,d,aliases); if (is.logical(x)) isTRUE(x[1]) else tolower(as.character(x[1])) %in% c('true','1','yes','y','on') }
  findcol <- function(d, requested, defaults, required=TRUE) { cn<-names(d); i<-match(tolower(c(requested,defaults)),tolower(cn)); i<-i[!is.na(i)]; if(length(i)) cn[i[1]] else if(required) fail('Required column not found',paste(c(requested,defaults),collapse=', ')) else NULL }
  signal_file <- relpath(op$signal %||% op$input %||% val('signal')) %||% relpath(val('input'))
  if (is.null(signal_file) || !file.exists(signal_file)) fail('Signal file not found', as.character(signal_file))
  sd <- readtab(signal_file); tc <- findcol(sd,val('track_column',NULL),c('track','cell_type')); pc <- findcol(sd,val('position_column',NULL),c('position','coordinate','genomic_position')); vc <- findcol(sd,val('value_column',NULL),c('value','signal','accessibility'))
  if (!is.null(op$signal) && !is.null(p$input_mode) && tolower(as.character(p$input_mode))=='wide') { tracks<-setdiff(names(sd),c(tc,pc)); sd<-do.call(rbind,lapply(tracks,function(z) data.frame(track=sd[[tc]],position=sd[[pc]],value=sd[[z]],stringsAsFactors=FALSE))); tc<-'track';pc<-'position';vc<-'value' }
  z <- data.frame(track=as.character(sd[[tc]]), position=suppressWarnings(as.numeric(sd[[pc]])), signal=suppressWarnings(as.numeric(sd[[vc]])), stringsAsFactors=FALSE)
  z <- z[nzchar(z$track) & is.finite(z$position) & !is.na(z$signal),,drop=FALSE]
  if (!nrow(z)) fail('No valid signal rows remain')
  na_action <- tolower(as.character(val('na_action','drop'))); if (na_action=='impute') z$signal[is.na(z$signal)] <- num('impute_value',0)
  inc<-vec(val('tracks_include')); exc<-vec(val('tracks_exclude')); if(length(inc)) z<-z[z$track%in%inc,,drop=FALSE]; if(length(exc)) z<-z[!z$track%in%exc,,drop=FALSE]; if(!nrow(z)) fail('No tracks remain after filtering')
  tracks <- unique(z$track); requested<-vec(val('track_order')); if(length(requested)) tracks<-c(requested,setdiff(tracks,requested)); tracks<-tracks[tracks%in%unique(z$track)]
  z$track <- factor(z$track, levels=tracks); z <- z[order(z$track,z$position),,drop=FALSE]
  transform <- tolower(as.character(val('signal_transform','none'))); if(transform=='log1p') z$signal<-log1p(pmax(z$signal,0)); if(transform=='sqrt') z$signal<-sqrt(pmax(z$signal,0))
  value_lim <- suppressWarnings(as.numeric(unlist(val('value_limits',NULL)))); if(length(value_lim)==2 && all(is.finite(value_lim)) && diff(value_lim)>0) z$signal <- pmin(value_lim[2],pmax(value_lim[1],z$signal))
  scale_mode <- tolower(as.character(val('signal_scale','none'))); normalize <- boo('normalize_per_track',FALSE); if(normalize) scale_mode<-'row'
  if(scale_mode=='row') z$scaled<-ave(z$signal,z$track,FUN=function(x) { r<-range(x,finite=TRUE); if(diff(r)==0) rep(0,length(x)) else (x-r[1])/diff(r) }) else if(scale_mode=='global') { r<-range(z$signal,finite=TRUE); z$scaled<-(z$signal-r[1])/ifelse(diff(r)==0,1,diff(r)) } else { r<-range(z$signal,finite=TRUE); z$scaled<-(z$signal-r[1])/ifelse(diff(r)==0,1,diff(r)) }
  if (tolower(as.character(val('signal_scale','none')))=='none' && !normalize) z$scaled<-ifelse(max(z$signal,na.rm=TRUE)==0,0,z$signal/max(z$signal,na.rm=TRUE))
  expr_file <- relpath(op$expression %||% val('expression'))
  ed <- NULL; e <- data.frame(track=character(),expression=numeric(),stringsAsFactors=FALSE)
  if(!is.null(expr_file) && file.exists(expr_file) && boo('expression_show',TRUE)) { ed<-readtab(expr_file); etc<-findcol(ed,val('expression_track_column',NULL),c('track','cell_type')); evc<-findcol(ed,val('expression_value_column',NULL),c('value','expression','gene_expression')); e<-data.frame(track=as.character(ed[[etc]]),expression=suppressWarnings(as.numeric(ed[[evc]])),stringsAsFactors=FALSE); e<-e[e$track%in%tracks&is.finite(e$expression),,drop=FALSE]; e$track<-factor(e$track,levels=tracks) }
  features_file<-relpath(op$features %||% val('features')); f<-data.frame(); if(!is.null(features_file)&&file.exists(features_file)) f<-readtab(features_file)
  annotations_file<-relpath(op$annotations %||% val('annotations')); ann<-data.frame(); if(!is.null(annotations_file)&&file.exists(annotations_file)) ann<-readtab(annotations_file)
  write.csv(z[,c('track','position','signal','scaled')],file.path(out,'signal_data_used.csv'),row.names=FALSE); write.csv(e,file.path(out,'expression_data_used.csv'),row.names=FALSE); write.csv(data.frame(track=tracks,order=seq_along(tracks)),file.path(out,'track_order.csv'),row.names=FALSE)
  lim<-suppressWarnings(as.numeric(unlist(val('position_limits',NULL)))); if(length(lim)!=2||any(!is.finite(lim))) lim<-range(z$position); if(lim[1]>lim[2]) lim<-rev(lim); if(diff(lim)==0) lim<-lim+c(-.5,.5)
  xlim<-suppressWarnings(as.numeric(unlist(val('expression_limits',NULL)))); if(length(xlim)!=2||any(!is.finite(xlim))) xlim<-if(nrow(e)) range(e$expression) else c(0,1); if(diff(xlim)==0) xlim<-xlim+c(-.5,.5)
  palval<-val('track_colors',NULL); pal<-scales::hue_pal()(length(tracks)); names(pal)<-tracks; if(!is.null(palval)) { pv<-unlist(palval); if(!is.null(names(pv))) pal[names(pv)[names(pv)%in%tracks]]<-as.character(pv[names(pv)%in%tracks]) else pal[seq_len(min(length(pv),length(pal)))]<-as.character(pv[seq_len(min(length(pv),length(pal)))]) }
  w<-num('width',14); h<-num('height',8); dpi<-num('dpi',300); base<-num('base_size',10); rowh<-.70/length(tracks); yt<-.82
  draw_static <- function() { grid.newpage(); grid.rect(gp=gpar(fill=val('plot_background','white'),col=NA)); mainx0<-.29; mainx1<-.75; ex0<-.80; ex1<-.98; ytop<-.84; ybot<-.14; yy<-ytop-(seq_along(tracks)-.5)*(ytop-ybot)/length(tracks); sx<-function(x) mainx0+(x-lim[1])/diff(lim)*(mainx1-mainx0); ex<-function(x) ex0+(x-xlim[1])/diff(xlim)*(ex1-ex0)
    if(boo('grid_show',TRUE)) for(x in pretty(lim,5)) grid.lines(unit(c(sx(x),sx(x)),'npc'),unit(c(ybot,ytop),'npc'),gp=gpar(col=val('grid_color','#E5E7EB'),lwd=num('grid_width',.5)))
    anncol <- if(nrow(ann)) setdiff(names(ann),findcol(ann,'track',c('track','cell_type')))[1] else NULL; annlevels <- if(!is.null(anncol)) unique(as.character(ann[[anncol]])) else character(); annpal <- if(length(annlevels)) setNames(scales::hue_pal()(length(annlevels)),annlevels) else character()
    for(i in seq_along(tracks)) { if(!is.null(anncol)){ av<-ann[as.character(ann[[findcol(ann,'track',c('track','cell_type'))]])==tracks[i],anncol]; if(length(av)&&nzchar(av[1])) grid.rect(x=unit(.278,'npc'),y=unit(yy[i],'npc'),width=unit(.012,'npc'),height=unit(abs(rowh)*.8,'npc'),gp=gpar(fill=annpal[as.character(av[1])],col=NA)) }; a<-z[z$track==tracks[i],]; a<-a[order(a$position),]; xx<-sx(a$position); by<-yy[i]-(a$scaled*.78*rowh/abs(rowh)); bline<-yy[i]+.34*rowh; if(boo('track_baseline_show',TRUE)) grid.lines(unit(c(mainx0,mainx1),'npc'),unit(rep(bline,2),'npc'),gp=gpar(col=val('track_baseline_color','#9CA3AF'),lwd=num('track_baseline_width',.5))); geom<-tolower(as.character(val('signal_geom','area'))); if(geom=='area'&&boo('track_fill',TRUE)) grid.polygon(unit(c(xx,rev(xx)),'npc'),unit(c(by,rep(bline,length(by))),'npc'),gp=gpar(fill=pal[i],col=NA,alpha=num('track_alpha',.75))); if(geom=='step') {ord<-order(xx); grid.lines(unit(xx[ord],'npc'),unit(by[ord],'npc'),gp=gpar(col=pal[i],lwd=num('track_outline_width',1.2))) } else grid.lines(unit(xx,'npc'),unit(by,'npc'),gp=gpar(col=pal[i],lwd=num('track_outline_width',1.2))); if(boo('track_label_show',TRUE)) grid.text(tracks[i],unit(.27,'npc'),unit(yy[i],'npc'),just='right',gp=gpar(col=val('track_label_color','#253044'),fontsize=num('track_label_size',base),fontfamily=val('font_family','sans'))) }
    if(nrow(e)) for(i in seq_along(tracks)) { a<-e[e$track==tracks[i],]; if(nrow(a)){ den<-density(a$expression,from=xlim[1],to=xlim[2],n=80); den$y<-den$y/max(den$y)*abs(rowh)*.32; grid.polygon(unit(c(ex(den$x),rev(ex(den$x))),'npc'),unit(c(yy[i]+den$y,rev(yy[i]-den$y)),'npc'),gp=gpar(fill=val('expression_fill','#94A3B8'),col=val('expression_outline','#475569'),alpha=num('expression_alpha',.8))); stat<-tolower(as.character(val('expression_statistic','median'))); if(stat!='none') grid.points(unit(ex(if(stat=='mean')mean(a$expression) else median(a$expression)),'npc'),unit(yy[i],'npc'),pch=18,gp=gpar(col=val('expression_outline','#1E293B')))} }
    grid.lines(unit(c(.775,.775),'npc'),unit(c(ybot,ytop),'npc'),gp=gpar(col='#64748B',lwd=1)); if(boo('expression_show',TRUE)) grid.text(val('expression_title','Gene expression'),unit((ex0+ex1)/2,'npc'),unit(.89,'npc'),gp=gpar(fontsize=num('title_size',16),fontface='bold')); if(boo('feature_show',FALSE)&&nrow(f)){ fc<-findcol(f,'start',c('start')); ec<-findcol(f,'end',c('end')); lc<-findcol(f,'label',c('label'),FALSE); for(j in seq_len(nrow(f))){ grid.rect(x=unit((sx(as.numeric(f[[fc]][j]))+sx(as.numeric(f[[ec]][j])))/2,'npc'),y=unit(.91,'npc'),width=unit(abs(sx(as.numeric(f[[ec]][j]))-sx(as.numeric(f[[fc]][j]))),'npc'),height=unit(num('feature_height',.025),'npc'),gp=gpar(fill=val('feature_fill','#CBD5E1'),col=val('feature_border','#64748B'))); if(!is.null(lc)&&boo('feature_label_show',TRUE)) grid.text(as.character(f[[lc]][j]),unit((sx(as.numeric(f[[fc]][j]))+sx(as.numeric(f[[ec]][j])))/2,'npc'),unit(.95,'npc'),rot=num('feature_label_angle',0),gp=gpar(fontsize=num('feature_label_size',9))) } }
    grid.text(val('xlab','Genomic position'),unit((mainx0+mainx1)/2,'npc'),unit(.07,'npc'),gp=gpar(fontsize=base)); grid.text(val('title','Genomic signal tracks'),unit(.5,'npc'),unit(.97,'npc'),gp=gpar(fontsize=num('title_size',18),fontface=val('title_face','bold'),col=val('title_color','#172033'))); if(!is.null(val('subtitle',NULL))) grid.text(val('subtitle'),unit(.5,'npc'),unit(.935,'npc'),gp=gpar(fontsize=num('subtitle_size',11),col='#64748B')); for(x in pretty(lim,5)) grid.text(format(x,trim=TRUE),unit(sx(x),'npc'),unit(.105,'npc'),gp=gpar(fontsize=num('x_tick_size',8)))
  }
  grDevices::svg(file.path(out,'result.svg'),width=w,height=h); draw_static(); dev.off(); grDevices::pdf(file.path(out,'result.pdf'),width=w/2.54,height=h/2.54); draw_static(); dev.off(); grDevices::png(file.path(out,'result.png'),width=w*dpi/2.54,height=h*dpi/2.54,res=dpi); draw_static(); dev.off()
  if(boo('interactive',TRUE)&&requireNamespace('plotly',quietly=TRUE)&&requireNamespace('htmlwidgets',quietly=TRUE)){ pl<-plotly::plot_ly(); for(i in seq_along(tracks)){a<-z[z$track==tracks[i],]; pl<-plotly::add_trace(pl,x=a$position,y=i-a$scaled*.78,type='scatter',mode=if(tolower(as.character(val('signal_geom','area')))=='area')'lines'else'lines',name=tracks[i],line=list(color=pal[i]),hovertemplate=paste0('Track: ',tracks[i],'<br>Position: %{x}<br>Signal: %{customdata}<extra></extra>'),customdata=a$signal,fill=if(tolower(as.character(val('signal_geom','area')))=='area')'tozeroy'else'none',xaxis='x',yaxis='y')}; if(nrow(e)) for(i in seq_along(tracks)){a<-e[e$track==tracks[i],]; if(nrow(a)) pl<-plotly::add_trace(pl,x=a$expression,y=rep(i,nrow(a)),type='violin',orientation='h',name=paste0(tracks[i],' expression'),legendgroup=tracks[i],showlegend=FALSE,fillcolor=val('expression_fill','#94A3B8'),line=list(color=val('expression_outline','#475569')),xaxis='x2',yaxis='y',hovertemplate=paste0('Track: ',tracks[i],'<br>Expression: %{x}<extra></extra>'))}; pl<-plotly::layout(pl,title=val('title','Genomic signal tracks'),xaxis=list(domain=c(.28,.75),range=lim,title=val('xlab','Genomic position')),xaxis2=list(domain=c(.80,.98),range=xlim,title=val('expression_axis_label','Gene expression')),yaxis=list(autorange='reversed',tickmode='array',tickvals=seq_along(tracks),ticktext=tracks,showticklabels=FALSE),showlegend=FALSE); pl<-plotly::config(pl,displaylogo=FALSE,scrollZoom=boo('zoom',TRUE),doubleClick=if(boo('reset_view',TRUE))'reset'else' autosize',modeBarButtonsToAdd=if(boo('lasso_select',FALSE))c('lasso2d','select2d') else character()); htmlwidgets::saveWidget(pl,file.path(out,'result.html'),selfcontained=TRUE) } else writeLines('<!doctype html><html><body><p>Interactive Plotly output is unavailable; see result.png.</p></body></html>',file.path(out,'result.html'))
  meta<-list(plugin='interactive_genomic_signal_track_plot',track_order=tracks,track_count=length(tracks),genomic_range=lim,signal_scale=scale_mode,signal_transform=transform,expression=list(show=boo('expression_show',TRUE),geom=val('expression_geom','violin'),limits=xlim,rows=nrow(e)),feature_count=nrow(f),input_summaries=list(signal_rows=nrow(z),expression_rows=nrow(e),annotation_rows=nrow(ann)),outputs=stale[stale!='error.json']); write(toJSON(meta,auto_unbox=TRUE,pretty=TRUE),file.path(out,'figure.json')); logmsg(sprintf('Rendered %d tracks, %d signal rows, %d expression rows',length(tracks),nrow(z),nrow(e)))
}, error=function(e) fail('Plot generation failed',conditionMessage(e)))
